def has_pair_with_sum(nums: list[int], target: int) -> bool:
    # Two-pointer after in-place sort: O(n log n) time, O(1) extra space
    nums.sort()
    left, right = 0, len(nums) - 1
    while left < right:
        current = nums[left] + nums[right]
        if current == target:
            return True
        elif current < target:
            left += 1
        else:
            right -= 1
    return False
```
Sorts in place, then uses two pointers — constant extra space.

